static std::unordered_map<std::string_view, std::string_view> s_compound_map;
static std::once_flag s_init_flag;

static void init_compound_map() {
    s_compound_map.reserve(sizeof(s_compound_table) / sizeof(s_compound_table[0]));
    for (const auto& entry : s_compound_table) {
        s_compound_map[entry.kanji] = entry.kana;
    }
}

static uint32_t decode_utf8(const char* ptr, size_t len, size_t& out_bytes) {
    if (len == 0) { out_bytes = 0; return 0; }
    unsigned char c = static_cast<unsigned char>(ptr[0]);
    if (c < 0x80) {
        out_bytes = 1;
        return c;
    } else if ((c & 0xE0) == 0xC0) {
        if (len < 2) { out_bytes = 1; return c; }
        out_bytes = 2;
        return ((c & 0x1F) << 6) | (static_cast<unsigned char>(ptr[1]) & 0x3F);
    } else if ((c & 0xF0) == 0xE0) {
        if (len < 3) { out_bytes = 1; return c; }
        out_bytes = 3;
        return ((c & 0x0F) << 12) |
               ((static_cast<unsigned char>(ptr[1]) & 0x3F) << 6) |
               (static_cast<unsigned char>(ptr[2]) & 0x3F);
    } else if ((c & 0xF8) == 0xF0) {
        if (len < 4) { out_bytes = 1; return c; }
        out_bytes = 4;
        return ((c & 0x07) << 18) |
               ((static_cast<unsigned char>(ptr[1]) & 0x3F) << 12) |
               ((static_cast<unsigned char>(ptr[2]) & 0x3F) << 6) |
               (static_cast<unsigned char>(ptr[3]) & 0x3F);
    }
    out_bytes = 1;
    return c;
}

bool contains_kanji(const std::string& input) {
    size_t i = 0;
    while (i < input.size()) {
        size_t b = 0;
        uint32_t cp = decode_utf8(&input[i], input.size() - i, b);
        if (b == 0) break;
        if ((cp >= 0x4E00 && cp <= 0x9FFF) || (cp >= 0x3400 && cp <= 0x4DBF)) {
            return true;
        }
        i += b;
    }
    return false;
}

std::string kanji_to_hiragana(const std::string& input) {
    std::call_once(s_init_flag, init_compound_map);

    std::string result;
    result.reserve(input.size() * 2);

    size_t i = 0;
    const size_t n = input.size();

    const size_t num_single_entries = sizeof(s_single_kanji_table) / sizeof(s_single_kanji_table[0]);

    while (i < n) {
        bool matched = false;

        // Try matching compound words up to 32 bytes (around 10 Japanese characters)
        size_t max_search_bytes = std::min<size_t>(32, n - i);
        for (size_t byte_len = max_search_bytes; byte_len >= 3; --byte_len) {
            std::string_view sub(&input[i], byte_len);
            auto it = s_compound_map.find(sub);
            if (it != s_compound_map.end()) {
                result.append(it->second);
                i += byte_len;
                matched = true;
                break;
            }
        }
        if (matched) continue;

        // Decode UTF-8 character
        size_t char_bytes = 0;
        uint32_t cp = decode_utf8(&input[i], n - i, char_bytes);
        if (char_bytes == 0) break;

        if ((cp >= 0x4E00 && cp <= 0x9FFF) || (cp >= 0x3400 && cp <= 0x4DBF)) {
            // Binary search in s_single_kanji_table
            SingleKanjiEntry key{cp, nullptr};
            auto it = std::lower_bound(
                s_single_kanji_table, s_single_kanji_table + num_single_entries, key,
                [](const SingleKanjiEntry& a, const SingleKanjiEntry& b) {
                    return a.codepoint < b.codepoint;
                }
            );
            if (it != s_single_kanji_table + num_single_entries && it->codepoint == cp && it->kana && it->kana[0] != 0) {
                result.append(it->kana);
            } else {
                result.append(&input[i], char_bytes);
            }
        } else {
            result.append(&input[i], char_bytes);
        }
        i += char_bytes;
    }

    return result;
}

